#[test]
#[cfg(unix)]
fn pwd_recovery() -> Result {
    let nu = nu_test_support::fs::executable_path().display().to_string();
    let unique = std::time::SystemTime::now()
        .duration_since(std::time::UNIX_EPOCH)
        .map(|duration| duration.as_nanos())
        .unwrap_or(0);
    let tmpdir = std::env::temp_dir()
        .join(format!("nu_pwd_recovery_{}_{}", std::process::id(), unique))
        .display()
        .to_string();

    let ctx = test_record! {
        "tmpdir" => tmpdir,
        "nu" => nu,
    };
    // We `cd` into a temporary directory, then spawn another `nu` process to
    // delete that directory. Then we attempt to recover by running `cd /`.
    let code = r#"
        let ctx = $in

        mkdir $ctx.tmpdir
        cd $ctx.tmpdir
        ^$ctx.nu -c $"cd /; rm -r '($ctx.tmpdir)'"
        cd /
        pwd
    "#;

    test().run_with_data(code, ctx).expect_value_eq("/")
}

use std::{env, path::PathBuf, sync::LazyLock};

fn main() {
    extract_build_profile();
}

static OUT_DIR: LazyLock<PathBuf> =
    LazyLock::new(|| PathBuf::from(env::var("OUT_DIR").expect("set by cargo")));

fn extract_build_profile() {
    let mut components = OUT_DIR.components().rev();
    let _out = components.next().expect("has `out` dir");
    let _crate = components.next().expect("has dir for crate");
    let _build = components.next().expect("has `build` dir");
    let profile = components.next().expect("has profile dir");
    let profile = profile.as_os_str().to_string_lossy();
    println!("cargo::rustc-env=BUILD_PROFILE={profile}");
}

